// Composable para NexusComponent
// Provee: state (librosDestacados, loading, error), cargarLibrosDestacados() y setupScrollAnimations()

import axios from 'axios';

export const useNexusComponent = () => {
  const state = {
    librosDestacados: [],
    loading: false,
    error: null
  };

  const cargarLibrosDestacados = async () => {
    try {
      state.loading = true;
      state.error = null;

      // Intentamos cargar desde el JSON público
      const response = await axios.get('/data/libros.json');
      if (response && response.data && Array.isArray(response.data.librosDestacados)) {
        state.librosDestacados = response.data.librosDestacados;
      } else {
        // Si la respuesta no contiene lo esperado, dejamos un array vacío
        state.librosDestacados = [];
      }
    } catch (err) {
      console.error('Error al cargar libros destacados:', err);
      state.error = 'No se pudieron cargar los libros destacados';
      // Opcional: fallback con datos estáticos mínimos
      state.librosDestacados = [
        { id: 0, titulo: 'Libro de ejemplo', autor: 'Autor', categoria: 'Categoría', rating: 4, portada: '' }
      ];
    } finally {
      state.loading = false;
    }
  };

  const setupScrollAnimations = () => {
    try {
      const io = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('animate-in');
            observer.unobserve(entry.target);
          }
        });
      }, { threshold: 0.12 });

      document.querySelectorAll('.scroll-animation').forEach(el => io.observe(el));
    } catch (e) {
      // Fallback: si IntersectionObserver no está disponible, revelamos todo
      document.querySelectorAll('.scroll-animation').forEach(el => el.classList.add('animate-in'));
    }
  };

  return {
    state,
    cargarLibrosDestacados,
    setupScrollAnimations
  };
};
